import React, { useEffect, useState } from 'react';
import { getCar } from '../services/carService';
import { getImageUrl } from '../services/api';
import { motion } from 'framer-motion';
import styles from './ComparePage.module.css';

const ComparePage = () => {
  const [cars, setCars] = useState([]);
  const compareList = JSON.parse(localStorage.getItem('compareList') || '[]');

  useEffect(() => {
    const fetchCars = async () => {
      const promises = compareList.map(id => getCar(id));
      const results = await Promise.all(promises);
      setCars(results.map(res => res.data));
    };
    if (compareList.length) fetchCars();
  }, []);

  if (!compareList.length) return <div className={styles.empty}>Выберите автомобили для сравнения</div>;

  const attributes = ['brand', 'model', 'year', 'price', 'body_type', 'restyling', 'description'];

  return (
    <motion.div className={styles.container} initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
      <h1 className={styles.title}>Сравнение автомобилей</h1>
      <table className={styles.table}>
        <thead>
          <tr>
            <th>Характеристика</th>
            {cars.map(car => (
              <th key={car.id}>{car.brand} {car.model}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {attributes.map(attr => (
            <tr key={attr}>
              <td className={styles.attrName}>{attr}</td>
              {cars.map(car => (
                <td key={car.id}>
                  {attr === 'image_url' ? <img src={getImageUrl(car.image_url)} alt="" className={styles.carImage} /> :
                   attr === 'restyling' ? (car.restyling ? 'Да' : 'Нет') :
                   attr === 'price' ? `${car.price.toLocaleString()} ₽` :
                   car[attr]}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </motion.div>
  );
};

export default ComparePage;
